INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'bulls-beat-ulster-34-26-loftus-2026-10-24',
  'Bulls hold off fightback to beat Ulster 34-26 at Loftus',
  'Sport', '2026-10-24', 'EWN', 'https://www.ewn.co.za/bulls-march-on-in-the-urc-with-a-decent-34-26-scalp-of-ulster-in-pretoria/',
  'The Bulls beat Ulster 34-26 at Loftus Versfeld on Saturday, surviving a second-half fightback from the Irish side.',
  'The Bulls beat Ulster 34-26 in a United Rugby Championship match at Loftus Versfeld in Pretoria last Saturday. The home side built a big first-half lead through three tries before Ulster rallied strongly in the second half, according to EWN and Rekord.

Hooker Johan Grobbelaar scored a try for the Bulls after the break as Ulster narrowed the gap late in the contest. Captain Marcell Coetzee, back from injury, received a yellow card during the match.

Coach Johan Ackermann said afterwards that the team was pleased to beat quality opposition but had conceded too many soft penalties, which let Ulster back into the game through lapses in discipline. He credited the players for holding on in the closing stages.

Flyhalf Handre Pollard left the field with a hamstring injury and lock Sango Xamlashe was also hurt during the match. The win keeps the Bulls near the top of the United Rugby Championship standings as they prepare to host the Scarlets at Loftus Versfeld next.',
  NULL, NULL, NULL,
  '["https://www.ewn.co.za/bulls-march-on-in-the-urc-with-a-decent-34-26-scalp-of-ulster-in-pretoria/", "https://www.citizen.co.za/rekord/sports-news/local-sports/2026/10/25/bulls-beat-ulster-in-pretorias-summer-heat-at-loftus/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'willem-strauss-re-elected-blue-bulls-president-2026-10-26',
  'Blue Bulls re-elect Willem Strauss unopposed as president',
  'Sport', '2026-10-26', 'Rekord', 'https://www.citizen.co.za/rekord/sports-news/local-sports/2026/10/26/willem-strauss-onbestrede-herkies-vir-n-vierde-termyn-as-bloubul-president/',
  'Willem Strauss was re-elected unopposed to a further four-year term as Blue Bulls Rugby Union president, the union said this week.',
  'Willem Strauss has been re-elected unopposed to a further four-year term as president of the Pretoria-based Blue Bulls Rugby Union, the union announced this week. He first took charge of the union in 2018 and has now served roughly eight years in the role, among its longest-serving presidents in the professional era.

Blue Bulls Company co-shareholders Johann Rupert and Patrice Motsepe both congratulated Strauss on his re-election. Rupert said Strauss has brought steadiness across the union''s structures, while Motsepe pointed to strong results from the union''s teams across competitions as a reflection of his leadership.

The union also confirmed that deputy president Ben Eybers was re-elected, and that seven new vice-presidents joined the board alongside Strauss. Strauss said he plans to keep serving the sport for as long as he can make a difference, with an ambition of building the Bulls into a leading rugby union both on and off the field.',
  NULL, NULL, NULL,
  '["https://www.citizen.co.za/rekord/sports-news/local-sports/2026/10/26/willem-strauss-onbestrede-herkies-vir-n-vierde-termyn-as-bloubul-president/", "https://www.billionaires.africa/2026/10/20/south-african-billionaires-johann-rupert-patrice-motsepe-back-bulls-rugby-bosss-third-term/"]',
  'agent'
);
